begin transaction read only;
with targets as (
 select c.* from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname='public' and c.relkind='r'
 and c.relname in ('tasks','notes','captures','activities','feedback','analytics_events')
), roles as (select oid,rolname from pg_roles where rolname in ('anon','authenticated','service_role'))
select jsonb_build_object(
 'connection',jsonb_build_object('read_only',current_setting('transaction_read_only')),
 'tables',(select jsonb_agg(jsonb_build_object('name',relname,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'force_rls',relforcerowsecurity) order by relname) from targets),
 'columns',(select jsonb_agg(jsonb_build_object('table',t.relname,'name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid,true),'identity',a.attidentity,'generated',a.attgenerated) order by t.relname,a.attnum) from targets t join pg_attribute a on a.attrelid=t.oid left join pg_attrdef d on d.adrelid=t.oid and d.adnum=a.attnum where a.attnum>0 and not a.attisdropped),
 'constraints',(select jsonb_agg(jsonb_build_object('table',t.relname,'name',c.conname,'kind',c.contype,'definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated,'deferrable',c.condeferrable,'initially_deferred',c.condeferred) order by t.relname,c.conname) from targets t join pg_constraint c on c.conrelid=t.oid),
 'indexes',(select jsonb_agg(jsonb_build_object('table',t.relname,'name',c.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) order by t.relname,c.relname) from targets t join pg_index i on i.indrelid=t.oid join pg_class c on c.oid=i.indexrelid),
 'policies',(select jsonb_agg(jsonb_build_object('table',t.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end order by r) from unnest(p.polroles) r),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by t.relname,p.polname) from targets t join pg_policy p on p.polrelid=t.oid),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'returns',pg_get_function_result(p.oid),'language',l.lanname,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'strict',p.proisstrict,'volatility',p.provolatile,'config',p.proconfig,'body_hash',md5(regexp_replace(p.prosrc,'\s+','','g')),'acl',(select jsonb_agg(jsonb_build_object('grantee',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by a.grantee,a.privilege_type) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname in ('set_updated_at','ingest_beta_analytics','record_beta_task_activation','record_beta_feedback_submission','beta_analytics_report')),
 'triggers',(select jsonb_agg(jsonb_build_object('table',t.relname,'name',g.tgname,'enabled',g.tgenabled,'definition',pg_get_triggerdef(g.oid,true)) order by t.relname,g.tgname) from targets t join pg_trigger g on g.tgrelid=t.oid where not g.tgisinternal),
 'table_grants',(select jsonb_agg(jsonb_build_object('table',t.relname,'grantee',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by t.relname,a.grantee,a.privilege_type) from targets t cross join lateral aclexplode(coalesce(t.relacl,acldefault('r',t.relowner))) a),
 'default_grants',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'GLOBAL'),'object_type',d.defaclobjtype,'grantee',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type) order by d.defaclrole,d.defaclnamespace,d.defaclobjtype,a.grantee,a.privilege_type) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) a where n.nspname='public' or d.defaclnamespace=0),
 'effective_grants',(select jsonb_agg(jsonb_build_object('table',t.relname,'role',r.rolname,'select',has_table_privilege(r.oid,t.oid,'SELECT'),'insert',has_table_privilege(r.oid,t.oid,'INSERT'),'update',has_table_privilege(r.oid,t.oid,'UPDATE'),'delete',has_table_privilege(r.oid,t.oid,'DELETE'),'truncate',has_table_privilege(r.oid,t.oid,'TRUNCATE'),'references',has_table_privilege(r.oid,t.oid,'REFERENCES'),'trigger',has_table_privilege(r.oid,t.oid,'TRIGGER')) order by t.relname,r.rolname) from targets t cross join roles r)
) as schema_metadata;
commit;
